216	int do_taskset(pid_t pid, unsigned long mask)
217	{
218	    // search the pcb
219	    pcb_t *set_pcb = NULL;
220	    for(int i = 0; i < NUM_MAX_TASK; i++){
221	        if(pcb[i].pid == pid){
222	            set_pcb = &pcb[i];
223	            break;
224	        }
225	    }
226	    if(set_pcb == NULL){
227	        return 0;
228	    }
229	
230	    set_pcb->mask = mask;
231	    return 1;
232	}
