234	// block the pcb task into the block queue
235	void do_block(list_node_t *pcb_node, list_head *queue)
236	{
237	    list_del(pcb_node);
238	    list_add_tail(pcb_node, queue);
239	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
240	}
