242	// unblock the `pcb` from the block queue
243	void do_unblock(list_node_t *pcb_node)
244	{
245	    list_del(pcb_node);
246	    list_add_tail(pcb_node, &ready_queue);
247	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
248	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
