16	// a simple hash function
17	static int futex_hash(uint64_t x)
18	{
19	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
20	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
21	    x = x ^ (x >> 31);
22	    return x % FUTEX_BUCKETS;
23	}
24	
25	static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
26	{
27	    int key = futex_hash((uint64_t)val_addr);
28	    list_node_t *head = &futex_buckets[key];
29	    for (list_node_t *p = head->next; p != head; p = p->next) {
30	        futex_node_t *node = list_entry(p, futex_node_t, list);
31	        if (node->futex_key == (uint64_t)val_addr) {
32	            return node;
33	        }
34	    }
35	
36	    if (create) {
37	        futex_node_t *node = (futex_node_t*) kmalloc(sizeof(futex_node_t));
38	        node->futex_key = (uint64_t)val_addr;
39	        init_list_head(&node->block_queue);
40	        list_add_tail(&node->list, &futex_buckets[key]);
41	        return node;
42	    }
43	
44	    return NULL;
45	}
46	
47	void futex_wait(volatile uint64_t *val_addr)
48	{
49	    disable_preempt();
50	
51	    futex_node_t *node = get_node(val_addr, 1);
52	    assert(node != NULL);
53	    do_block(&current_running[cpu_id]->list, &node->block_queue);
54	    scheduler();
55	
56	    enable_preempt();
57	}
58	
59	void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
60	{
61	    disable_preempt();
62	    futex_node_t *node = get_node(val_addr, 0);
63	
64	    if (node != NULL) {
65	        for (int i = 0; i < num_wakeup; ++i) {
66	            if (list_empty(&node->block_queue)) break;
67	
68	            do_unblock(node->block_queue.next);
69	        }
70	    }
71	
72	    scheduler();
73	    enable_preempt();
