61	void test_shell()
62	{
63	    char blank_command[] = "                                                      ";
64	    char prompt[] = "> liangliang678@UCAS_OS: ";
65	
66	    const int SHELL_COMMAND_BEGIN = strlen(prompt) + 1;
67	    const int SHELL_COMMAND_END   = SHELL_WIDTH;
68	    int print_location_x;
69	    int print_location_y;
70	    int input, buf_p;
71	    char buffer[100];
72	
73	    char prev_command[MAX_PREV][100] = {0};
74	    for(int i = 0; i < MAX_PREV; i++){
75	        strcpy(prev_command[i], "\0");
76	    }
77	    int back_times = 0;
78	
79	    sys_screen_clear(1, SHELL_END);
80	    sys_move_cursor(1, SHELL_BEGIN);
81	    printf("------------------- COMMAND -------------------");
82	    sys_move_cursor(1, SHELL_END);
83	    printf("------------------- COMMAND -------------------");
84	
85	    print_location_y = SHELL_BEGIN + 1;
86	    sys_move_cursor(1, print_location_y);
87	    while (1)
88	    {   
89	        if(print_location_y == SHELL_END){
90	            print_location_y--;
91	            sys_move_cursor(1, print_location_y);
92	            sys_screen_scroll(SHELL_BEGIN + 1, SHELL_END - 1);    
93	        }
94	        printf("%s", prompt);
95	
96	        // call syscall to read UART port
97	        buf_p = 0;
98	        print_location_x = SHELL_COMMAND_BEGIN;
99	        while((input = getchar()) != 13 && input != '\n'){
100	            if(input == '\b' || input == 127){
101	                if(buf_p > 0){
102	                    print_location_x--;
103	                    buf_p--;
104	                    sys_move_cursor(print_location_x, print_location_y);
105	                    printf(" ");
106	                    sys_move_cursor(print_location_x, print_location_y);
107	                }           
108	            }
109	            else if(input == 27){
110	                if(back_times < MAX_PREV){
111	                    strcpy(buffer, prev_command[back_times++]);
112	                    print_location_x = SHELL_COMMAND_BEGIN;
113	                    sys_move_cursor(print_location_x, print_location_y);
114	                    printf("%s", blank_command);
115	                    sys_move_cursor(print_location_x, print_location_y);
116	                    printf("%s", buffer);
117	                    print_location_x += strlen(buffer);
118	                    buf_p = strlen(buffer);
119	                }
120	            }
121	            else{
122	                if(print_location_x < SHELL_COMMAND_END){
123	                    buffer[buf_p++] = (char)input;
124	                    print_location_x++;
125	                    printf("%c",input);
126	                }             
127	            }
128	        }
129	        buffer[buf_p++] = '\0';
130	        for(int i = MAX_PREV - 1; i > 0; i--){
131	            strcpy(prev_command[i], prev_command[i-1]);
132	        }
133	        strcpy(prev_command[0], buffer);
134	        printf("\n");
135	        print_location_y++;
136	        back_times = 0;
137	
138	        // parse input (ps, exec, kill, clear, reset)
139	        int argc = 0;
