141	        int argv_p = 0;
142	        int in_argv_flag = 0;
143	 
144	        for(int i = 0; ; i++){
145	            if(buffer[i] == ' ' || buffer[i] == '\0'){
146	                if(in_argv_flag){
147	                    if(argc >= MAX_ARGC){
148	                        if(print_location_y == SHELL_END){
149	                            print_location_y--;
150	                            sys_move_cursor(1, print_location_y);
