11	void ready_to_exit_task()
12	{
13	    int i = 0, print_location = 1;
14	
15	    int lock1_id = sys_binsem_get(LOCK1_BINSEM_KEY);
16	    int lock2_id = sys_binsem_get(LOCK2_BINSEM_KEY);
17	
18	    sys_binsem_op(lock1_id, BINSEM_OP_LOCK);
19	    sys_binsem_op(lock2_id, BINSEM_OP_LOCK);
20	
21	    for (i = 0; i < 1000; i++)
22	    {
23	        sys_move_cursor(1, print_location);
24	        printf("> [TASK] I am task with pid %d, I have acquired two binsem lock. (%d)", sys_getpid(), i++);
25	    }
26	
27	    sys_exit(); // test exit
28	}
