30	void wait_lock_task(long other_pid)
31	{
32	    int print_location = 2;
33	
34	    sys_move_cursor(1, print_location);
35	    printf("> [TASK] I want to acquire a binsem lock from task(pid=%ld).", (long)other_pid);
36	
37	    int lock1_id = sys_binsem_get(LOCK1_BINSEM_KEY);
38	    sys_binsem_op(lock1_id, BINSEM_OP_LOCK);
39	
40	    sys_move_cursor(1, print_location);
41	    printf("> [TASK] I have acquired a mutex lock from task(pid=%ld).   ", (long)other_pid);
42	
43	    sys_binsem_op(lock1_id, BINSEM_OP_UNLOCK);
44	
45	    sys_exit(); // test exit
46	}
