48	void wait_exit_task()
49	{
50	    struct task_info task1 = {(uintptr_t)&ready_to_exit_task, USER_PROCESS};
51	    struct task_info task2 = {(uintptr_t)&wait_lock_task, USER_PROCESS};
52	
53	    pid_t pid_task1 = sys_spawn(&task1, NULL, ENTER_ZOMBIE_ON_EXIT);
54	    sys_spawn(&task2, (void*)(long)pid_task1, AUTO_CLEANUP_ON_EXIT);
55	
56	    int print_location = 3;
57	
58	    sys_move_cursor(1, print_location);
59	    printf("> [TASK] I want to wait task (pid=%ld) to exit.", pid_task1);
60	
61	    sys_waitpid(pid_task1); //test waitpid
62	
63	    sys_move_cursor(1, print_location);
64	    printf("> [TASK] Task (pid=%d) has exited.                ", pid_task1);
65	
66	    sys_exit(); // test exit
67	}

