6	
7	binsem_node_t binsem_nodes[BINSEM_NUMBER];
8	// a simple hash function
9	static int binsem_hash(uint64_t x)
10	{
11	    x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ul;
12	    x = (x ^ (x >> 27)) * 0x94d049bb133111ebul;
13	    x = x ^ (x >> 31);
14	    return x % BINSEM_NUMBER;
15	}
16	
17	void init_system_binsem()
18	{
19	    for(int i = 0; i < BINSEM_NUMBER; i++){
20	        binsem_nodes[i].sem = 1;
21	        init_list_head(&binsem_nodes[i].block_queue);
22	    }
23	}
24	
25	int binsem_get(int key)
26	{ 
27	    return binsem_hash((uint64_t)key);
28	}
29	
30	void binsem_op(int binsem_id, int op)
31	{
32	    disable_preempt();
33	
34	    binsem_node_t *node = &binsem_nodes[binsem_id];
35	
36	    if(op == BINSEM_OP_LOCK){
37	        node->sem--;
38	        if(node->sem < 0){
39	            do_block(&current_running[cpu_id]->list, &node->block_queue);
40	            scheduler();
41	        }
42	        else{
43	            current_running[cpu_id]->binsem_id[current_running[cpu_id]->binsem_num] = binsem_id;
44	            current_running[cpu_id]->binsem_num++;
45	        }
46	    }
47	    else if(op == BINSEM_OP_UNLOCK){
48	        node->sem++;
49	        current_running[cpu_id]->binsem_num--;
50	        if(node->sem <= 0){
51	            list_node_t * unblocked_pcb_list = node->block_queue.next;
52	            pcb_t *unblocked_pcb = list_entry(unblocked_pcb_list, pcb_t, list);
53	            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
54	            unblocked_pcb->binsem_num++; 
55	            do_unblock(unblocked_pcb_list); 
56	            scheduler();        
57	        }
58	    }
59	
60	    enable_preempt();
61	}

