55	// block the pcb task into the block queue
56	void do_block(list_node_t *pcb_node, list_head *queue)
57	{
58	    list_del(pcb_node);
59	    list_add_tail(pcb_node, queue);
60	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
61	}
