63	// unblock the `pcb` from the block queue
64	void do_unblock(list_node_t *pcb_node)
65	{
66	    list_del(pcb_node);
67	    list_add_tail(pcb_node, &ready_queue);
68	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
69	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
