7	void mthread_barrier_init(mthread_barrier_t * barrier, unsigned count)
8	{
9	    barrier->count = count;
10	    atomic_exchange(&barrier->reached, 0);
11	    barrier->binsem_id = sys_binsem_get((int)barrier);
