13	void mthread_barrier_wait(mthread_barrier_t *barrier)
14	{
15	    sys_binsem_op(barrier->binsem_id, BINSEM_OP_LOCK);
16	    fetch_add(&barrier->reached, 1);
17	    if((barrier->reached) == (barrier->count)){
18	        atomic_exchange(&barrier->reached, 0);
19	        sys_binsem_op(barrier->binsem_id, BINSEM_OP_UNLOCK);
20	        sys_futex_wakeup((unsigned long*)barrier, barrier->count);                    
21	    }
22	    else{
23	        sys_binsem_op(barrier->binsem_id, BINSEM_OP_UNLOCK);      
24	        sys_futex_wait((unsigned long*)barrier);
25	    }
26	}
27	void mthread_barrier_destroy(mthread_barrier_t *barrier)
28	{
29	    barrier->count = -1;
30	    barrier->reached = -1;
31	}
