43	}
44	int mthread_cond_wait(mthread_cond_t *cond, int binsem_id)
45	{
46	    fetch_add(cond, 1);
47	    sys_binsem_op(binsem_id, BINSEM_OP_UNLOCK);
48	    sys_futex_wait((unsigned long*)cond);
49	    sys_binsem_op(binsem_id, BINSEM_OP_LOCK);
