void scheduler(void)
{
    pcb_t *cur_running = current_running[cpu_id];

    /* put the current task back to the ready queue if it is still runnable
     * (the kernel pcbs of both harts are never queued) */
    if(cur_running->status == TASK_RUNNING){
        cur_running->status = TASK_READY;
        cur_running->ready_tick = get_ticks();
        if(cur_running->pid != 0){
            list_add_tail(&cur_running->list, &ready_queue);
        }
    }

    /* pick the highest priority task allowed to run on this core;
     * run the kernel pcb of this core if there is no such task */
    list_node_t *next_node = max_priority_node();
    pcb_t *next_running;
    if(next_node == NULL){
        next_running = &kernel_pcb[cpu_id];
    }
    else{
        list_del(next_node);
        next_running = list_entry(next_node, pcb_t, list);
    }

    next_running->status = TASK_RUNNING;
    next_running->cpu_id = cpu_id;
    current_running[cpu_id] = next_running;
    current_cpu_running = next_running;
}

