args.new_string:
/* release all the binsems held by `p`, waking up one waiter per binsem */
static void release_binsems(pcb_t *p)
{
    for(int i = 0; i < p->binsem_num; i++){
        int binsem_id = p->binsem_id[i];
        binsem_node_t *node = &binsem_nodes[binsem_id];
        node->sem++;
        if(node->sem <= 0 && !list_empty(&node->block_queue)){
            list_node_t *unblocked_node = node->block_queue.next;
            pcb_t *unblocked_pcb = list_entry(unblocked_node, pcb_t, list);
            unblocked_pcb->binsem_id[unblocked_pcb->binsem_num] = binsem_id;
            unblocked_pcb->binsem_num++;
            do_unblock(unblocked_node);
        }
    }
    p->binsem_num = 0;
}

void do_exit()
{
    disable_preempt();

    pcb_t *exit_pcb = current_running[cpu_id];

    /* release all the binsems held by this task */
    release_binsems(exit_pcb);

    /* release the user stack */
    freePage(exit_pcb->user_stack_base, 1);

    /* wake up all the tasks waiting for this task */
    while(!list_empty(&exit_pcb->wait_list)){
        do_unblock(exit_pcb->wait_list.next);
    }

    if(exit_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
        /* become a zombie, `do_waitpid` will release the kernel stack */
        exit_pcb->status = TASK_ZOMBIE;
    }
    else{
        /* hand the pcb over to the kernel for cleanup */
        exit_pcb->status = TASK_EXITED;
        list_add_tail(&exit_pcb->list, &kernel_pcb[0].wait_list);
    }

    /* reschedule because the current_running is exited */
    scheduler();
    enable_preempt();
}

int do_kill(pid_t pid)
{
    disable_preempt();

    /* search the pcb */
    pcb_t *kill_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            kill_pcb = &pcb[i];
            break;
        }
    }
    if(kill_pcb == NULL){
        enable_preempt();
        return 0;
    }

    /* remove the task from its queue (ready / blocked / sleep);
     * a no-op if the task is running and thus not queued */
    list_del(&kill_pcb->list);

    /* release all the binsems held by this task */
    release_binsems(kill_pcb);

    /* release the user stack */
    freePage(kill_pcb->user_stack_base, 1);

    /* wake up all the tasks waiting for this task */
    while(!list_empty(&kill_pcb->wait_list)){
        do_unblock(kill_pcb->wait_list.next);
    }

    if(kill_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
        kill_pcb->status = TASK_ZOMBIE;
    }
    else{
        kill_pcb->status = TASK_EXITED;
        list_add_tail(&kill_pcb->list, &kernel_pcb[0].wait_list);
    }

    /* reschedule if the task killed itself */
    if(kill_pcb == current_running[cpu_id]){
        scheduler();
    }

    enable_preempt();
    return 1;
}

