args.new_string:
int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, regs_context_t *regs)
{
    disable_preempt();

    /* search the pcb */
    pcb_t *wait_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            wait_pcb = &pcb[i];
            break;
        }
    }
    if(wait_pcb == NULL){
        enable_preempt();
        return 0;
    }

    /* block until the target task exits */
    if(wait_pcb->status != TASK_ZOMBIE && wait_pcb->status != TASK_EXITED){
        do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
        scheduler();
    }

    /* reap the zombie: release the pcb and the kernel stack
     * (only the first woken waiter does this) */
    if(wait_pcb->status == TASK_ZOMBIE){
        wait_pcb->status = TASK_EXITED;
        wait_pcb->pid = -1;
        freePage(wait_pcb->kernel_stack_base, 1);
    }

    enable_preempt();
    return pid;
}

