args.new_string:
list_node_t* max_priority_node(void)
{
    list_node_t *max_node = NULL;
    pcb_t *max_pcb = NULL;

    /* search the ready queue for the highest priority task whose
     * hart mask allows it to run on this core; the task that became
     * ready first wins among tasks with the same priority */
    for(list_node_t *node = ready_queue.next; node != &ready_queue; node = node->next){
        pcb_t *check_pcb = list_entry(node, pcb_t, list);
        if(!(check_pcb->mask & (1lu << cpu_id))){
            continue;
        }
        if(max_node == NULL ||
           check_pcb->priority > max_pcb->priority ||
           (check_pcb->priority == max_pcb->priority &&
            check_pcb->ready_tick < max_pcb->ready_tick)){
            max_node = node;
            max_pcb = check_pcb;
        }
    }
    return max_node;
}

